-- BNW + Community Patch v151; append after released civilizations.
-- Only expose verified notification hooks; no CityConnections pathfinding veto.
UPDATE CustomModOptions SET Value=1 WHERE Name IN ('EVENTS_CITY_CAPITAL','EVENTS_PLAYER_TURN');
CREATE TEMP TABLE CONICALClone AS SELECT * FROM "Civilizations" WHERE Type='CIVILIZATION_AMERICA';
UPDATE CONICALClone SET "ID"=NULL,"Type"='CIVILIZATION_CONICAL_UNION',"Description"='TXT_KEY_CONICAL_CIV',"ShortDescription"='TXT_KEY_CONICAL_SHORT',"Adjective"='TXT_KEY_CONICAL_ADJECTIVE',"Civilopedia"='TXT_KEY_CONICAL_CIV_PEDIA',"CivilopediaTag"='TXT_KEY_CONICAL_CIV5',"Strategy"='TXT_KEY_CONICAL_STRATEGY',"DefaultPlayerColor"='PLAYERCOLOR_CONICAL',"Playable"=1,"AIPlayable"=0,"PackageID"=NULL,"DawnOfManQuote"='TXT_KEY_CONICAL_DAWN',"DawnOfManAudio"='',"DawnOfManImage"='CONICAL_Dawn.dds',"MapImage"='CONICAL_Map.dds',"PortraitIndex"=0,"IconAtlas"='CONICAL_CIV_ATLAS',"AlphaIconAtlas"='CONICAL_ALPHA_ATLAS';
DROP TABLE CONICALClone;
CREATE TEMP TABLE CONICALClone AS SELECT * FROM "Leaders" WHERE Type='LEADER_WASHINGTON';
UPDATE CONICALClone SET "ID"=NULL,"Type"='LEADER_CONICAL_BOLLARD',"Description"='TXT_KEY_CONICAL_LEADER',"Civilopedia"='TXT_KEY_CONICAL_LEADER_PEDIA',"CivilopediaTag"='TXT_KEY_CONICAL_BOLLARD',"PackageID"=NULL,"PortraitIndex"=0,"IconAtlas"='CONICAL_LEADER_ATLAS',"ArtDefineTag"='CONICAL_LeaderScene.xml';
DROP TABLE CONICALClone;
CREATE TEMP TABLE CONICALClone AS SELECT * FROM "Units" WHERE Type='UNIT_WORKER';
UPDATE CONICALClone SET "ID"=NULL,"Type"='UNIT_CONICAL_ROAD_CREW',"Description"='TXT_KEY_CONICAL_UNIT',"Civilopedia"='TXT_KEY_CONICAL_UNIT_PEDIA',"Help"='TXT_KEY_CONICAL_UNIT_HELP',"Strategy"='TXT_KEY_CONICAL_UNIT_STRATEGY',"IconAtlas"='CONICAL_OBJECT_ATLAS',"PortraitIndex"=1,"UnitFlagAtlas"='CONICAL_FLAG_ATLAS',"UnitFlagIconOffset"=0;
DROP TABLE CONICALClone;
-- Integer base work rate: CP v151 Worker 100 -> 125, before native shared modifiers.
UPDATE Units SET Moves=Moves+1,WorkRate=WorkRate*5/4 WHERE Type='UNIT_CONICAL_ROAD_CREW';
CREATE TEMP TABLE CONICALClone AS SELECT * FROM "Buildings" WHERE Type='BUILDING_WALLS';
UPDATE CONICALClone SET "ID"=NULL,"Type"='BUILDING_CONICAL_DETOUR_OFFICE',"Description"='TXT_KEY_CONICAL_OFFICE',"Civilopedia"='TXT_KEY_CONICAL_OFFICE_PEDIA',"Help"='TXT_KEY_CONICAL_OFFICE_HELP',"Strategy"='TXT_KEY_CONICAL_OFFICE_STRATEGY',"IconAtlas"='CONICAL_OBJECT_ATLAS',"PortraitIndex"=0;
DROP TABLE CONICALClone;
